    -- ========== ULTIMATE AUTO-RETRY FUNCTION ==========
    local function smartCheckKeyWithRetry(key, isRetryMode)
        if not key or key == "" then return nil, "Empty key" end
        
        -- Kiểm tra cache thành công (valid 10 phút)
        if successCache[key] and os.time() - successCache[key].timestamp < 600 then
            return successCache[key].result, "From success cache (retry " .. successCache[key].retryCount .. ")"
        end
        
        -- Kiểm tra cache thất bại (cache 30 giây để tránh spam)
        if failedCache[key] and os.time() - failedCache[key].timestamp < 30 then
            if not isRetryMode then
                return nil, "Recently failed, retrying..."
            end
        end
        
        -- Rate limiting
        local currentTime = tick()
        local timeSinceLast = currentTime - lastRequestTime
        
        if timeSinceLast < MIN_REQUEST_INTERVAL then
            task.wait(MIN_REQUEST_INTERVAL - timeSinceLast)
        end
        
        lastRequestTime = tick()
        requestCount = requestCount + 1
        
        -- Thực hiện request với timeout
        local result, errorMsg = nil, "Unknown error"
        
        for attempt = 1, 2 do -- Thử 2 lần nhanh trước khi bắt đầu retry
            local success, checkResult = pcall(function()
                return Junkie.check_key(key)
            end)
            
            if success and checkResult then
                if checkResult.valid then
                    -- THÀNH CÔNG: Lưu cache
                    successCache[key] = {
                        result = checkResult,
                        timestamp = os.time(),
                        retryCount = attempt
                    }
                    
                    -- Xóa khỏi failed cache
                    failedCache[key] = nil
                    pendingRetries[key] = nil
                    
                    -- Log history
                    table.insert(retryHistory, {
                        key = string.sub(key, 1, 8) .. "...",
                        success = true,
                        attempts = attempt,
                        timestamp = os.time(),
                        message = checkResult.message or "Success"
                    })
                    
                    -- Giới hạn history size
                    if #retryHistory > 100 then
                        table.remove(retryHistory, 1)
                    end
                    
                    return checkResult, "Success (attempt " .. attempt .. ")"
                else
                    errorMsg = "Key invalid"
                end
            else
                errorMsg = "Network error"
            end
            
            -- Small delay giữa các attempt nhanh
            if attempt < 2 then
                task.wait(0.3)
            end
        end
        
        -- Nếu fail 2 lần nhanh, bắt đầu auto-retry sequence
        if not isRetryMode then
            failedCache[key] = {
                timestamp = os.time(),
                attempts = 2
            }
            
            -- Bắt đầu retry sequence
            pendingRetries[key] = {
                startTime = os.time(),
                maxRetries = MAX_AUTO_RETRIES,
                currentRetry = 0
            }
            
            return nil, "Starting auto-retry sequence..."
        end
        
        return nil, errorMsg
    end

    -- ========== AUTO-RETRY SEQUENCE FUNCTION ==========
    local function executeAutoRetrySequence(key)
        if pendingRetries[key] and pendingRetries[key].currentRetry >= pendingRetries[key].maxRetries then
            return nil, "Max retries reached"
        end
        
        if not pendingRetries[key] then
            pendingRetries[key] = {
                startTime = os.time(),
                maxRetries = MAX_AUTO_RETRIES,
                currentRetry = 0
            }
        end
        
        local retryInfo = pendingRetries[key]
        
        for retry = retryInfo.currentRetry + 1, MAX_AUTO_RETRIES do
            retryInfo.currentRetry = retry
            
            -- Tính delay cho lần retry này
            local delay = RETRY_DELAYS[math.min(retry, #RETRY_DELAYS)]
            
            -- Hiển thị thông tin retry
            if _G.RetryUIUpdate then
                _G.RetryUIUpdate(key, retry, MAX_AUTO_RETRIES, delay)
            end
            
            -- Đợi delay
            task.wait(delay)
            
            -- Thực hiện check
            local result, message = smartCheckKeyWithRetry(key, true)
            
            if result and result.valid then
                -- THÀNH CÔNG SAU RETRY
                if _G.RetrySuccess then
                    _G.RetrySuccess(key, retry)
                end
                
                -- Log retry success
                table.insert(retryHistory, {
                    key = string.sub(key, 1, 8) .. "...",
                    success = true,
                    attempts = retry + 2, -- +2 vì đã thử 2 lần ban đầu
                    timestamp = os.time(),
                    message = "Success after " .. retry .. " retries"
                })
                
                pendingRetries[key] = nil
                return result, "Success after " .. retry .. " retries"
            end
            
            -- Log retry failure
            table.insert(retryHistory, {
                key = string.sub(key, 1, 8) .. "...",
                success = false,
                attempts = retry,
                timestamp = os.time(),
                message = "Retry " .. retry .. " failed"
            })
            
            -- Nếu là lần cuối
            if retry == MAX_AUTO_RETRIES then
                pendingRetries[key] = nil
                failedCache[key] = {
                    timestamp = os.time(),
                    attempts = MAX_AUTO_RETRIES + 2,
                    permanent = true
                }
                return nil, "All retries failed"
            end
        end
        
        return nil, "Retry sequence interrupted"
    end

    -- ========== MAIN CHECK FUNCTION WITH AUTO-RETRY ==========
    local function checkKeyWithAutoRetry(key)
        if not key or key == "" then
            return false, "No key provided"
        end
        
        if #key < 10 or #key > 100 then
            return false, "Invalid key format"
        end
        
        -- Thử check bình thường trước
        local result, message = smartCheckKeyWithRetry(key, false)
        
        if result and result.valid then
            return true, message
        end
        
        -- Nếu fail, bắt đầu auto-retry sequence
        task.spawn(function()
            local retryResult, retryMessage = executeAutoRetrySequence(key)
            
            if retryResult and retryResult.valid then
                -- Gọi callback nếu có
                if _G.OnAutoRetrySuccess then
                    _G.OnAutoRetrySuccess(key, retryMessage)
                end
            else
                -- Gọi callback nếu có
                if _G.OnAutoRetryFailure then
                    _G.OnAutoRetryFailure(key, retryMessage)
                end
            end
        end)
        
        -- Trả về ngay để không block UI
        return false, "Checking... (auto-retry enabled)"
    end

    -- ========== BATCH CHECK WITH RETRY ==========
    local function batchCheckKeysWithRetry(keys)
        local results = {}
        local promises = {}
        
        for _, key in ipairs(keys) do
            local promise = task.spawn(function()
                local success, message = checkKeyWithAutoRetry(key)
                return {
                    key = key,
                    success = success,
                    message = message,
                    timestamp = os.time()
                }
            end)
            table.insert(promises, promise)
        end
        
        -- Đợi tất cả promises
        for i, promise in ipairs(promises) do
            local result = promise:await()
            results[result.key] = result
        end
        
        return results
    end
    
    -- ========== OTHER FUNCTIONS ==========
    local function hasFileSystemSupport()
        local hasWritefile = pcall(function() return type(writefile) == "function" end)
        local hasReadfile = pcall(function() return type(readfile) == "function" end)
        local hasIsfile = pcall(function() return type(isfile) == "function" end)
        return hasWritefile and hasReadfile and hasIsfile
    end
    
    local fileSystemSupported = hasFileSystemSupport()
    
    local function getKeyFileName()
        if currentPlayerUserId > 0 then
            return "junkie_key_" .. tostring(currentPlayerUserId) .. ".json"
        else
            return "junkie_key_" .. string.gsub(currentPlayerName, "[^%w]", "_") .. ".json"
        end
    end
    
    local function saveVerifiedKey(key)
        if not fileSystemSupported then return false end
        
        local saveData = {
            key = key,
            username = currentPlayerName,
            userId = currentPlayerUserId,
            timestamp = os.time(),
            version = "2.3", -- Version với auto-retry
            lastVerified = os.time(),
            verifiedCount = 1,
            retryUsed = (pendingRetries[key] and pendingRetries[key].currentRetry) or 0
        }
        
        local fileName = getKeyFileName()
        local ok = pcall(function()
            local jsonData = HttpService:JSONEncode(saveData)
            writefile(fileName, jsonData)
        end)
        return ok
    end
    
    local function loadVerifiedKey()
        if not fileSystemSupported then 
            return nil, nil, nil
        end
        
        local fileName = getKeyFileName()
        local ok, content = pcall(function()
            if not isfile(fileName) then
                return nil
            end
            return readfile(fileName)
        end)
        
        if not ok or not content then 
            return nil, nil, nil
        end
        
        local success, data = pcall(function()
            return HttpService:JSONDecode(content)
        end)
        
        if success and data and data.key and data.username then
            -- Key cache 1 ngày
            if data.lastVerified and (os.time() - data.lastVerified) > (24 * 60 * 60) then
                return nil, nil, nil
            end
            return data.key, data.username, data.userId
        end
        
        return nil, nil, nil
    end
    
    local function checkKeylessMode()
        local result, message = smartCheckKeyWithRetry("KEYLESS", false)
        return result and result.valid and result.message == "KEYLESS"
    end
    
    local function clearSavedKey()
        if not fileSystemSupported then return false end
        local fileName = getKeyFileName()
        local ok = pcall(function() 
            if isfile(fileName) then
                delfile(fileName)
            end
        end)
        return ok
    end
    
    local function getAllSavedKeys()
        if not fileSystemSupported then return {} end
        
        local savedKeys = {}
        
        pcall(function()
            local possibleFiles = {
                "junkie_verified_key.json",
                getKeyFileName()
            }
            
            if currentPlayerUserId > 0 then
                for i = 1, 20 do
                    table.insert(possibleFiles, "junkie_key_" .. tostring(i) .. ".json")
                end
            end
            
            for _, fileName in ipairs(possibleFiles) do
                pcall(function()
                    if isfile(fileName) then
                        local content = readfile(fileName)
                        if content then
                            local data = HttpService:JSONDecode(content)
                            if data and data.key and data.username then
                                table.insert(savedKeys, {
                                    filename = fileName,
                                    username = data.username,
                                    userId = data.userId or 0,
                                    keyPreview = string.sub(data.key, 1, 8) .. "...",
                                    lastVerified = data.lastVerified or 0,
                                    verifiedCount = data.verifiedCount or 1,
                                    retryUsed = data.retryUsed or 0
                                })
                            end
                        end
                    end
                end)
            end
        end)
        
        return savedKeys
    end
    
    local function validateKeyWithUser(savedUsername, savedUserId)
        if not savedUsername then
            return false, "No saved user data"
        end
        
        if currentPlayerName ~= savedUsername then
            return false, "Key belongs to: " .. savedUsername
        end
        
        if savedUserId and savedUserId > 0 and currentPlayerUserId ~= savedUserId then
            return false, "User ID mismatch"
        end
        
        return true, "User verified"
    end

