            -- ========== RETRY UI UPDATERS ==========
            _G.RetryUIUpdate = function(key, retryCount, maxRetries, delay)
                if self.elements and self.elements.retryStatusFrame then
                    self.elements.retryStatusFrame.Visible = true
                    self.elements.retryText.Text = "Auto-retry attempt " .. retryCount
                    self.elements.retryProgressText.Text = "Attempt " .. retryCount .. "/" .. maxRetries .. " • Next in " .. delay .. "s"
                    
                    local progress = retryCount / maxRetries
                    TweenService:Create(self.elements.retryProgressBar, TweenInfo.new(0.3), {
                        Size = UDim2.new(progress, -20, 0, 4)
                    }):Play()
                    
                    -- Blink status light
                    TweenService:Create(self.elements.retryStatusLight, TweenInfo.new(0.5, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1), {
                        BackgroundColor3 = Colors.retry,
                        BackgroundTransparency = 0.3
                    }):Play()
                end
            end
            
            _G.RetrySuccess = function(key, retryCount)
                if self.elements and self.elements.retryStatusFrame then
                    self.elements.retryStatusFrame.Visible = false
                    self.elements.retryStatusLight.BackgroundColor3 = Colors.success
                    
                    self:updateStatus("✓ Success after " .. retryCount .. " retries!", Colors.success, 3)
                    
                    -- Animate success
                    if self.animateSuccess then
                        self:animateSuccess()
                    end
                end
            end
            
            _G.OnAutoRetrySuccess = function(key, message)
                saveVerifiedKey(key)
                getgenv().SCRIPT_KEY = key
                
                task.wait(1.5)
                if self.close then
                    self:close()
                end
            end
            
            _G.OnAutoRetryFailure = function(key, message)
                if self.elements then
                    self.elements.retryStatusFrame.Visible = false
                    self.elements.retryStatusLight.BackgroundColor3 = Colors.error
                    
                    self:updateStatus("✗ " .. message, Colors.error, 3)
                    self:showKeyWarning("Key verification failed")
                    
                    if self.setButtonLoading then
                        self:setButtonLoading(self.elements.verifyButton, "Verify Key", false)
                    end
                    
                    if self.elements.keyInput then
                        self.elements.keyInput.Interactable = true
                    end
                end
            end
            
            -- ========== UPDATED VERIFY FUNCTION ==========
            self.handleVerifyKey = function(self)
                local key = self.elements.keyInput.Text:gsub("%s+", "")
                
                if key == "" then
                    self:updateStatus("Please enter a key", Colors.error, 3)
                    self:shakeInput()
                    return
                end
                
                if #key < 10 then
                    self:updateStatus("Key too short", Colors.error, 3)
                    self:shakeInput()
                    return
                end
                
                -- Update UI
                if self.setButtonLoading then
                    self:setButtonLoading(self.elements.verifyButton, "Checking...", true)
                end
                
                self:updateStatus("Starting verification...", Colors.primary, 0)
                self.elements.keyInput.Interactable = false
                self.elements.retryStatusLight.BackgroundColor3 = Colors.warning
                
                -- Thực hiện check với auto-retry
                local success, message = checkKeyWithAutoRetry(key)
                
                -- Nếu thành công ngay lần đầu
                if success then
                    saveVerifiedKey(key)
                    self:updateStatus("✓ " .. message, Colors.success, 0)
                    
                    if self.animateSuccess then
                        self:animateSuccess()
                    end
                    
                    task.wait(1)
                    getgenv().SCRIPT_KEY = key
                    self:close()
                else
                    -- Nếu đang retry, UI sẽ được update qua callbacks
                    if message == "Checking... (auto-retry enabled)" then
                        self:updateStatus("Auto-retry started...", Colors.retry, 0)
                        self.elements.retryStatusLight.BackgroundColor3 = Colors.retry
                    else
                        -- Nếu fail ngay
                        self:updateStatus("✗ " .. message, Colors.error, 3)
                        self:showKeyWarning("Verification failed")
                        
                        if self.setButtonLoading then
                            self:setButtonLoading(self.elements.verifyButton, "Verify Key", false)
                        end
                        self.elements.keyInput.Interactable = true
                    end
                end
            end
            
            -- Các hàm UI khác (giữ nguyên)
            self.showSuccess = function(self, message)
                -- ... (giữ nguyên)
            end
            
            self.updateStatus = function(self, message, color, duration)
                -- ... (giữ nguyên)
            end
            
            self.setButtonLoading = function(self, button, text, loading)
                -- ... (giữ nguyên)
            end
            
            self.shakeInput = function(self)
                -- ... (giữ nguyên)
            end
            
            self.animateSuccess = function(self)
                -- ... (giữ nguyên)
            end
            
            self.close = function(self)
                -- ... (giữ nguyên)
            end
            
            self.setLoadingState = function(self, isLoading, message)
                -- ... (giữ nguyên)
            end
            
            self.showKeyWarning = function(self, message)
                -- ... (giữ nguyên)
            end
            
