            end
            
            self.showAccountInfo = function(self)
                -- ... (giữ nguyên)
            end
            
            -- Setup và return
            setupAnimations()
            animateEntrance()
            self.gui.Parent = game:GetService("CoreGui")
            
            return self.gui
        end
        end 
    end 
    
    local UI = {}
    UI.__index = UI
    
    function UI.new(options)
        local self = setmetatable({}, UI)
        
        self.options = options or {}
        self.title = self.options.title or "Auto-Retry Verification System"
        self.subtitle = self.options.subtitle or "Keys will auto-retry until successful"
        self.description = self.options.description or "Enter key to begin automatic verification"
        
        self.player = Players.LocalPlayer
        self.gui = nil
        self._connections = {}
        
        return self
    end
    
    UI.createUI = function(self)
        local UIFactory = loadUIFactory()
        
        if UIFactory then
            local uiBuilder = UIFactory(Colors, Players, TweenService, UserInputService, Lighting)
            if uiBuilder then
                uiBuilder(self)
            else
                error("UI builder initialization failed")
                return
            end
        else
            error("Failed to load UI factory")
            return
        end
        
        -- Connect events
        if self.elements then
            if self.elements.closeButton then
                table.insert(self._connections, self.elements.closeButton.MouseButton1Click:Connect(function()
                    self:close()
                end))
            end
            
            if self.elements.accountInfoBtn then
                table.insert(self._connections, self.elements.accountInfoBtn.MouseButton1Click:Connect(function()
                    self:showAccountInfo()
                end))
            end
            
            if self.elements.getLinkButton then
                table.insert(self._connections, self.elements.getLinkButton.MouseButton1Click:Connect(function()
                    self:handleGetLink()
                end))
            end
            
            if self.elements.verifyButton then
                table.insert(self._connections, self.elements.verifyButton.MouseButton1Click:Connect(function()
                    self:handleVerifyKey()
                end))
            end
            
            if self.elements.keyInput then
                table.insert(self._connections, self.elements.keyInput.FocusLost:Connect(function(enterPressed)
                    if enterPressed then
                        self:handleVerifyKey()
                    end
                end))
            end
        end
        
        return self.gui
    end
    
    function UI:close()
        getgenv().UI_CLOSED = true
        for _, conn in ipairs(self._connections or {}) do
            pcall(function() conn:Disconnect() end)
        end
        self._connections = {}
        if self.gui then self.gui:Destroy() end
        return getgenv().SCRIPT_KEY
    end
    
    function UI:handleGetLink()
        local secureGetKeyLink = Junkie.get_key_link()
        if not secureGetKeyLink then
            self:updateStatus("System not initialized", Colors.error, 3)
            return
        end
        local link = secureGetKeyLink
        
        if link then
            if setclipboard then
                setclipboard(link)
                self:updateStatus("Link copied to clipboard!", Colors.success, 3)
            else
                self:updateStatus("Get link: " .. link, Colors.primary, 10)
            end
        else
            self:updateStatus("Failed to get link", Colors.error, 3)
        end
    end

    -- ========== MAIN EXECUTION ==========
    local ui = UI.new()
    ui:createUI()

    -- Check keyless mode
    if ui.setLoadingState then
        ui:setLoadingState(true, "Checking keyless mode...")
    end
    
    task.wait(1)
    
    local keylessValid = checkKeylessMode()
    if keylessValid then
        if ui.showSuccess then
            ui:showSuccess("Keyless Mode ✓")
        end
        getgenv().SCRIPT_KEY = "KEYLESS"
        task.wait(1)
        if ui.close then ui:close() end
        return
    end
    
    -- Check saved key với auto-retry
    if ui.setLoadingState then
        ui:setLoadingState(true, "Checking saved key...")
    end
    
    task.wait(1.5)
    
    if ui.updateUserInfo then
        ui:updateUserInfo(currentPlayerName)
    end
    
    local savedKey, savedUsername, savedUserId = loadVerifiedKey()
    
    if savedKey and savedUsername then
        local userValid, userMessage = validateKeyWithUser(savedUsername, savedUserId)
        
        if userValid then
            task.wait(1)
            
            -- Check với auto-retry
            local keyValid, keyMessage = checkKeyWithAutoRetry(savedKey)
            
            if keyValid then
                if ui.showSuccess then
                    ui:showSuccess("Welcome back, " .. savedUsername .. "! ✓")
                end
                
                if ui.autoFillSavedKey then
                    ui:autoFillSavedKey(savedKey)
                end
                
                getgenv().SCRIPT_KEY = savedKey
                
                task.wait(1.5)
                if ui.close then 
                    ui:close() 
                end
                return
            else
                -- Key đã expired, xóa và show UI
                clearSavedKey()
                
                if ui.setLoadingState then
                    ui:setLoadingState(false)
                end
                
                ui:showKeyWarning("Saved key expired, please enter new key")
            end
        else
            ui:showKeyWarning(userMessage)
            task.wait(1)
            
            if ui.setLoadingState then
                ui:setLoadingState(false)
            end
        end
    else
        if ui.setLoadingState then
            ui:setLoadingState(false)
        end
    end

    -- Main loop
    while not getgenv().UI_CLOSED do
        task.wait(0.1)
        
        -- Auto clear status
        if ui.elements and ui.elements.statusText and ui.elements.statusText.Visible then
            task.wait(5)
            if ui.elements and ui.elements.statusText then
                ui.elements.statusText.Visible = false
            end
        end
    end
    
    return getgenv().SCRIPT_KEY
end)()

